Here is the problem description:
<problem_description>
Bear Limak prepares problems for a programming competition. Of course, it would be unprofessional to mention the sponsor name in the statement. Limak takes it seriously and he is going to change some words. To make it still possible to read, he will try to modify each word as little as possible.Limak has a string s that consists of uppercase English letters. In one move he can swap two adjacent letters of the string. For example, he can transform a string "ABBC" into "BABC" or "ABCB" in one move.Limak wants to obtain a string without a substring "VK" (i.e. there should be no letter 'V' immediately followed by letter 'K'). It can be easily proved that it's possible for any initial string s.What is the minimum possible number of moves Limak can do?
</problem_description>

Here is the Java 8 code you have to repair:
<original_code>
import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) {
        new Main().run();
    }

    void run() {
        InputReader in = new InputReader(System.in);
        PrintWriter out = new PrintWriter(System.out);
        TaskC solver = new TaskC();
        solver.solve(1, in, out);
        out.flush();
    }

    static class TaskC {
        static final int INF = (int) 1e9;

        public void solve(int testNumber, InputReader in, PrintWriter out) {
            int n = in.nextInt();
            String s = in.next();
            int nk = 0, nv = 0, no = 0;
            int[] kpos = new int[n], vpos = new int[n], opos = new int[n];
            int[] snk = new int[n + 1], snv = new int[n + 1], sno = new int[n + 1];

            for (int i = 0; i < n; ++i) {
                char ch = s.charAt(i);
                if (ch == 'V') vpos[nv++] = i;
                else if (ch == 'K') kpos[nk++] = i;
                else opos[no++] = i;
                snk[i + 1] = nk;
                snv[i + 1] = nv;
                sno[i + 1] = no;
            }

            int[][][][] best = new int[2][nk + 1][nv + 1][no + 1];
            for (int[][][] x : best) 
                for (int[][] y : x) 
                    for (int[] z : y) 
                        Arrays.fill(z, INF);

            best[0][0][0][0] = 0;

            for (int k = 0; k <= nk; ++k) {
                for (int v = 0; v <= nv; ++v) {
                    for (int o = 0; o <= no; ++o) {
                        for (int hv = 0; hv < 2; ++hv) {
                            int cur = best[hv][k][v][o];
                            if (cur == INF) continue;

                            if (k < nk && hv == 0) {
                                int cost = Math.max(snv[kpos[k]] - v, 0) + Math.max(sno[kpos[k]] - o, 0);
                                best[0][k + 1][v][o] = Math.min(best[0][k + 1][v][o], cur + cost);
                            }
                            if (v < nv) {
                                int cost = Math.max(snk[vpos[v]] - k, 0) + Math.max(sno[vpos[v]] - o, 0);
                                best[1][k][v + 1][o] = Math.min(best[1][k][v + 1][o], cur + cost);
                            }
                            if (o < no) {
                                int cost = Math.max(snv[opos[o]] - v, 0) + Math.max(snk[opos[o]] - k, 0);
                                best[0][k][v][o + 1] = Math.min(best[0][k][v][o + 1], cur + cost);
                            }
                        }
                    }
                }
            }

            out.println(Math.min(best[0][nk][nv][no], best[1][nk][nv][no]));
        }
    }

    static class InputReader {
        public BufferedReader reader;
        public StringTokenizer tokenizer;

        public InputReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream), 32768);
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}
